// Il prospect del giro in corso. 'Prepara + Pre-filtro' gira a ogni giro
// del ciclo, quindi e la fonte sicura per sapere di chi stiamo parlando.
const base = $('Prepara + Pre-filtro').first().json || {};

// ATTENZIONE, trappola: $('Nodo').first() restituisce l'ultima esecuzione di
// quel nodo, non per forza quella del giro in corso. Un prospect senza sito
// non passa da 'Estrai email + P.IVA': senza questo controllo si prendono i
// dati del prospect precedente, che finisce in Notion una seconda volta.
// Quindi accettiamo i dati di un ramo solo se parlano dello stesso place_id.
function datiDelGiro(nodo) {
  try {
    const j = $(nodo).first().json;
    return (j && j.place_id && j.place_id === base.place_id) ? j : null;
  } catch (e) { return null; }
}

const prev = datiDelGiro('Estrai email + P.IVA')
  || datiDelGiro('Senza sito (niente email)')
  || base;

// La risposta puo contenere blocchi 'thinking' prima del testo: prendi solo i blocchi 'text'.
const resp = $input.first().json || {};
const blocchi = Array.isArray(resp.content) ? resp.content : [];
const raw = blocchi.filter(b => b && b.type === 'text').map(b => b.text || '').join('\n').trim();

let data = {};
let errore = '';
let jsonStr = raw;
const a = jsonStr.indexOf('{');
const b = jsonStr.lastIndexOf('}');
if (a !== -1 && b !== -1) jsonStr = jsonStr.slice(a, b + 1);
try { data = JSON.parse(jsonStr); }
catch (e) { errore = 'parsing fallito: ' + (raw.slice(0, 200) || resp.stop_reason || 'risposta vuota'); }

return [{ json: {
  ...prev,
  punteggio:          data.punteggio || 'Medio',
  motivo:             data.motivo || errore || '',
  stimaCollaboratori: data.stimaCollaboratori || 'incerto',
  prima_riga:         data.prima_riga || '',
  errore_qualifica:   errore,
}}];

const sd = $getWorkflowStaticData('global');
sd.creati = (sd.creati || 0) + 1;
const r = $input.first().json || {};
return [{ json: { creato: true, notion_url: r.url || '', notion_id: r.id || '' } }];

// Tiene il conto dei motivi di scarto: senza questo non si sa mai
// perche una run trova poco.
const sd = $getWorkflowStaticData('global');
sd.scartati = (sd.scartati || 0) + 1;
if (!sd.motiviScarto) sd.motiviScarto = {};

const j = $input.first().json || {};
const motivo = j.motivoScarto
  || (j.punteggio === 'Basso' ? 'punteggio Basso' : 'altro');
sd.motiviScarto[motivo] = (sd.motiviScarto[motivo] || 0) + 1;

return [{ json: { scartato: true, nome: j.nome || '', motivo } }];

const sd = $getWorkflowStaticData('global');
const creati = sd.creati || 0;
const duplicati = sd.duplicati || 0;
const scartati = sd.scartati || 0;
const analizzati = creati + duplicati + scartati;

const motivi = sd.motiviScarto || {};
const dettaglioScarti = Object.keys(motivi).length
  ? Object.keys(motivi).map(m => m + ': ' + motivi[m]).join(' | ')
  : 'nessuno';

const messaggio = 'Prospezione artigiani finita. Nuovi in Notion: ' + creati
  + ' | gia presenti: ' + duplicati
  + ' | scartati: ' + scartati
  + ' | analizzati: ' + analizzati;

console.log(messaggio);
console.log('Motivi di scarto -> ' + dettaglioScarti);
console.log('Pagine Google lette: ' + (sd.pagineLette || 0)
  + ' | risultati grezzi: ' + ((sd.risultati || []).length));

return [{ json: {
  creati, duplicati, scartati, analizzati,
  motiviScarto: motivi,
  erroriRicerca: sd.erroriRicerca || [],
  pagineLette: sd.pagineLette || 0,
  risultatiGrezzi: (sd.risultati || []).length,
  messaggio,
  dettaglioScarti,
}}];
